'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const data=window.GRADA_DATA;
const loaded=!!(data&&data.metadata&&Array.isArray(data.players)&&data.players.length&&Array.isArray(data.teams));
let view='overview',pos='Todos',unit='total',sort='goals',direction=-1,choices=[];
const labels={name:'Jugador',team:'Equipo',pos:'Posición',matches:'PJ',minutes:'Min',goals:'Goles',assists:'Asist.',xg:'xG',xa:'xA derivada',conversion:'Conv. %',delta:'Goles − xG',passes:'Pases',completed:'Completados',accuracy:'Pases %',shots:'Tiros',saves:'Paradas',savepct:'Paradas %',conceded:'Goles rec.',xga:'xG recibidos',psxg:'PSxG',prevented:'Goles evitados',clean:'Porterías a 0',tackles:'Entradas',interceptions:'Intercepc.',keypasses:'Pases clave',progressive:'Pases progres.'};
const rates=new Set(['goals','assists','xg','xa','delta','passes','completed','shots','saves','conceded','xga','tackles','interceptions','keypasses','progressive']);
const playerkeys=['matches','minutes','goals','assists','xg','xa','shots','conversion','delta','passes','accuracy','keypasses','progressive','tackles','interceptions'];
const keeperkeys=['matches','minutes','saves','savepct','conceded','xga','psxg','prevented','clean','passes','accuracy'];
const teamkeys=['matches','goals','xg','delta','conceded','xga','passes','accuracy'];
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function initials(s){return String(s).split(' ').map(w=>w[0]).slice(0,2).join('');}
function players(){return loaded?data.players:[];}
function teams(){return loaded?data.teams:[];}
function metric(p,k){const n=p[k];return typeof n!=='number'||!Number.isFinite(n)?null:unit==='90'&&rates.has(k)?p.minutes>0?n*90/p.minutes:null:n;}
function val(p,k){const n=metric(p,k);if(n===null)return '—';if(typeof n!=='number')return esc(n);return new Intl.NumberFormat('es-ES',{maximumFractionDigits:unit==='90'&&rates.has(k)?2:['xg','xa','delta','conversion','savepct','xga','psxg','prevented','minutes'].includes(k)?1:0}).format(n);}
function compare(a,b,key=sort){let x=metric(a,key),y=metric(b,key);if(key==='name'||key==='team'||key==='pos'){x=a[key];y=b[key];}if(x===null&&y===null)return a.name.localeCompare(b.name);if(x===null)return 1;if(y===null)return -1;let d=typeof x==='string'?x.localeCompare(y):x-y;return d?direction*d:a.name.localeCompare(b.name);}
function columns(){let base=view==='teams'?['name',...teamkeys]:pos==='POR'?['name','team','minutes','saves','savepct','conceded','xga','clean']:pos==='DEF'?['name','team','minutes','tackles','interceptions','passes','accuracy','progressive']:pos==='MED'?['name','team','minutes','goals','assists','xa','keypasses','accuracy']:['name','team','pos','minutes','goals','assists','xg','xa','conversion'];if(labels[sort]&&!base.includes(sort))base.push(sort);return base;}
function rows(){const search=$('#search').value.trim().toLocaleLowerCase('es');const tf=$('#teamfilter').value;return (view==='teams'?teams():players().filter(p=>(pos==='Todos'||p.pos===pos)&&(!tf||p.team===tf))).filter(p=>(p.name+' '+(p.team||'')).toLocaleLowerCase('es').includes(search)).sort((a,b)=>compare(a,b));}
function renderTable(){const cols=columns(),a=rows();$('#thead').innerHTML='<tr><th>#</th>'+cols.map(k=>'<th><button data-sort="'+k+'">'+(k==='name'&&view==='teams'?'Equipo':labels[k])+(sort===k?(direction<0?' ↓':' ↑'):'')+'</button></th>').join('')+'</tr>';$('#tbody').innerHTML=a.map((p,i)=>'<tr><td>'+String(i+1).padStart(2,'0')+'</td>'+cols.map(k=>'<td class="'+(['goals','xg','saves'].includes(k)?'highlight':'')+'">'+(k==='name'?'<button class="namebtn" data-detail="'+p.id+'"><span class="initials">'+esc(initials(p.name))+'</span>'+esc(p.name)+'</button>':k==='pos'?'<span class="pos">'+esc(p.pos)+'</span>':k==='team'?esc(p.team):val(p,k))+'</td>').join('')+'</tr>').join('')||'<tr><td colspan="'+(cols.length+1)+'" class="empty">'+(loaded?'No hay resultados con estos filtros.':'Aún no hay datos importados. Consulta las instrucciones de carga.')+'</td></tr>';$('#count').textContent=a.length+' '+(view==='teams'?'equipos':'jugadores')+(loaded?' · StatsBomb Open Data':' · sin datos cargados')+(unit==='90'?' · métricas de volumen por 90 min':'');$$('[data-sort]').forEach(b=>b.onclick=()=>{direction=sort===b.dataset.sort?-direction:-1;sort=b.dataset.sort;renderTable();});$$('[data-detail]').forEach(b=>b.onclick=()=>detail(+b.dataset.detail,view==='teams'));$('#export').disabled=!loaded||!a.length;}
function renderLeaders(){const categories=[['Goles','goals'],['Asistencias','assists'],['Goles esperados','xg'],['xA derivada de tiros','xa'],['Precisión de pase','accuracy'],['Paradas','saves']];$('#leaders').innerHTML=categories.map(([title,key])=>{let list=players().filter(p=>(key==='saves'?p.pos==='POR':p.pos!=='POR')&&metric(p,key)!==null&&(key!=='accuracy'||p.passes>=30)).sort((a,b)=>(metric(b,key)-metric(a,key))||a.name.localeCompare(b.name)).slice(0,5);return '<article class="leadercard"><h3>'+title+(unit==='90'&&rates.has(key)?' / 90 min':'')+'</h3>'+list.map((p,i)=>'<div class="leaderrow"><span class="leaderplace">'+(i+1)+'</span><button class="namebtn" data-leader-profile="'+p.id+'"><span class="initials">'+esc(initials(p.name))+'</span><span>'+esc(p.name)+'<small>'+esc(p.team)+'</small></span></button><strong>'+val(p,key)+(key==='accuracy'?'%':'')+'</strong></div>').join('')+(list.length?'':'<p class="empty">Sin datos importados</p>')+'<button class="leaderlink" data-leader-sort="'+key+'">Ver ranking completo →</button></article>';}).join('');$$('[data-leader-profile]').forEach(b=>b.onclick=()=>detail(+b.dataset.leaderProfile,false));$$('[data-leader-sort]').forEach(b=>b.onclick=()=>{sort=b.dataset.leaderSort;pos=sort==='saves'?'POR':'Todos';direction=-1;$('#search').value='';$('#teamfilter').value='';$$('[data-pos]').forEach(q=>q.classList.toggle('on',q.dataset.pos===pos));navigate('players');});}
function dashboard(){const ts=teams(),ps=players(),g=ts.reduce((s,p)=>s+p.goals,0),xg=ts.reduce((s,p)=>s+p.xg,0),as=ps.reduce((s,p)=>s+p.assists,0),saves=ps.reduce((s,p)=>s+p.saves,0);const values=[['Goles',g,'Marcadores de los partidos'],['Goles esperados · xG',xg,'Suma del xG de los tiros'],['Asistencias',as,'Pases marcados como asistencia'],['Paradas',saves,'Tiros detenidos por el portero']];$('#cards').innerHTML=values.map(([title,value,note])=>'<div class="card"><div class="label">'+title+'</div><strong>'+(!loaded?'—':new Intl.NumberFormat('es-ES',{maximumFractionDigits:1}).format(value))+'</strong><small>'+note+' · totales</small></div>').join('');const top=[...ts].sort((a,b)=>(metric(b,'xg')??-1)-(metric(a,'xg')??-1)).slice(0,5);$('#ranks').innerHTML=top.map((t,i)=>'<div class="rank"><span class="ranknum">'+(i+1)+'</span><span class="crest">'+esc(initials(t.name))+'</span><div class="rankname">'+esc(t.name)+'<small>'+t.matches+' partidos · '+t.goals+' goles</small></div><div class="rankscore">'+val(t,'xg')+'</div></div>').join('')||'<p class="empty">Sin datos importados</p>';const matches=loaded?data.matches:[];if(!matches.length){$('#chart').innerHTML='<p class="empty">El gráfico se generará a partir de los partidos importados.</p>';$('#insight').textContent='No se muestran estimaciones sin una fuente de datos.';return;}let goals=0,expected=0;const points=matches.map(m=>{goals+=m.home_goals+m.away_goals;expected+=m.home_xg+m.away_xg;return [goals,expected];});const max=Math.ceil(Math.max(goals,expected)/10)*10||10;const px=i=>35+(points.length===1?0:i/(points.length-1)*470);const py=y=>175-y/max*150;$('#chart').innerHTML='<svg viewBox="0 0 540 210" role="img" aria-label="Goles y xG acumulados de los partidos importados">'+[0,1,2,3].map(i=>'<line x1="35" x2="505" y1="'+py(max*i/3)+'" y2="'+py(max*i/3)+'" stroke="#dce0e3"/><text x="2" y="'+(py(max*i/3)+4)+'">'+Math.round(max*i/3)+'</text>').join('')+'<polyline points="'+points.map((v,i)=>px(i)+','+py(v[1])).join(' ')+'" fill="none" stroke="#8f99a4" stroke-width="2" stroke-dasharray="5 5"/><polyline points="'+points.map((v,i)=>px(i)+','+py(v[0])).join(' ')+'" fill="none" stroke="#c9182b" stroke-width="2.5"/><text x="35" y="202">Partido 1</text><text x="430" y="202">Partido '+matches.length+'</text></svg>';$('#insight').textContent=matches.length+' partidos importados · '+new Intl.NumberFormat('es-ES',{maximumFractionDigits:1}).format(goals-expected)+' goles respecto al xG. Tandas excluidas.';}
function renderCompare(){const a=players();if(!a.length){$('#comparegrid').innerHTML='<p class="panel empty">Importa los datos para comparar jugadores reales.</p>';return;}if(!choices.length||choices.some(id=>!a.find(p=>p.id===id)))choices=a.slice(0,2).map(p=>p.id);$('#comparegrid').innerHTML=choices.map((id,i)=>{const p=a.find(p=>p.id===id),keys=p.pos==='POR'?keeperkeys:playerkeys;return '<div class="panel"><p class="sub">JUGADOR '+(i+1)+'</p><select class="compareselect" data-compare="'+i+'" aria-label="Jugador '+(i+1)+'">'+a.map(q=>'<option value="'+q.id+'" '+(q.id===id?'selected':'')+'>'+esc(q.name)+'</option>').join('')+'</select><h2>'+esc(p.name)+'</h2><p class="sub">'+esc(p.team)+' · '+esc(p.pos)+'</p>'+keys.map(k=>'<div class="comparestat"><span>'+labels[k]+'</span><b>'+val(p,k)+'</b></div>').join('')+'</div>';}).join('');$$('[data-compare]').forEach(e=>e.onchange=()=>{choices[+e.dataset.compare]=+e.value;renderCompare();});}
function detail(id,isTeam){const p=(isTeam?teams():players()).find(p=>p.id===id);if(!p)return;const keys=isTeam?teamkeys:p.pos==='POR'?keeperkeys:playerkeys;$('#detailbody').innerHTML='<span class="badge">STATSBOMB OPEN DATA</span><h1 class="detailtitle">'+esc(p.name)+'</h1><p class="sub">'+esc(p.team||data.metadata.competition)+' · '+esc(data.metadata.season)+(unit==='90'?' · métricas de volumen por 90 min':'')+'</p><div class="detailstats">'+keys.map(k=>'<div class="comparestat"><span>'+labels[k]+'</span><b>'+val(p,k)+'</b></div>').join('')+'</div><p class="sub note">— = no disponible. PSxG y goles evitados no se incluyen en esta importación. xA derivada del xG de los tiros asistidos.</p>';$('#detail').showModal();}
function navigate(v){view=v;const info={overview:['Vista general','Estadísticas de fútbol','Líderes, rankings y estadísticas de jugadores y equipos.'],players:['Jugadores','Estadísticas de jugadores','Datos reales de los partidos importados de StatsBomb Open Data.'],teams:['Equipos','Estadísticas de equipos','Ataque, defensa y distribución de las selecciones.'],compare:['Comparador','Comparador de jugadores','Contrasta perfiles y métricas en su contexto.'],glossary:['Glosario','Glosario de métricas','Definiciones y límites de los datos disponibles.']}[v];$('#crumb').textContent=info[0];$('#pagetitle').textContent=info[1];$('#pagesub').textContent=info[2];$$('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===v));$('#overview').classList.toggle('hidden',v!=='overview');$('#listing').classList.toggle('hidden',!['overview','teams','players'].includes(v));$('#compare').classList.toggle('hidden',v!=='compare');$('#glossary').classList.toggle('hidden',v!=='glossary');$('#filters').classList.toggle('hidden',v==='glossary');$('#export').classList.toggle('hidden',['compare','glossary'].includes(v));$('#positions').classList.toggle('hidden',v==='teams');$('#teamfilter').classList.toggle('hidden',v==='teams');$('#allplayers').classList.toggle('hidden',v!=='overview');$('#tabletitle').textContent=v==='teams'?'Ranking de equipos':'Ranking de jugadores';$('#tablesub').textContent='Selecciona un nombre para ver su perfil. — = no disponible.';renderTable();renderCompare();window.scrollTo({top:0,behavior:'smooth'});}
const terms=[['xG · Goles esperados','Suma del campo shot.statsbomb_xg: probabilidad de gol de cada tiro según el modelo StatsBomb. Incluye penaltis durante el partido; excluye tandas.'],['xA derivada de tiros','Suma del xG de los tiros enlazados directamente con un pase mediante assisted_shot_id. Es una métrica calculada por GRADA a partir de los tiros asistidos, no un modelo independiente para todos los pases.'],['Conversión y goles − xG','Conversión = goles / tiros × 100. Goles − xG mide la diferencia entre goles marcados por el jugador y xG acumulado. Los goles de equipo incluyen autogoles.'],['Paradas y xG recibidos','Paradas: tiros rivales con resultado Saved, Saved to Post o Saved Off Target, asignados al portero presente. xG recibidos incluye todos los tiros rivales durante sus intervalos en portería.'],['PSxG y goles evitados','No disponibles en esta importación. El xG previo al tiro no permite calcular de forma equivalente los goles evitados. Se muestran con —.'],['Precisión de pase','Pases completados / intentados × 100. StatsBomb indica los pases no completados con pass.outcome. El panel de líderes exige al menos 30 intentos para esta métrica.'],['Pases clave y progresivos','Pase clave: pass.shot_assist. Pase progresivo: pase completado que avanza al menos 10 metros en el eje del campo; se convierten las 120 unidades de StatsBomb a 105 metros. Es una definición local de GRADA.'],['Minutos y por 90','Se suman los intervalos de posición de las alineaciones, con límite de 90 o 120 minutos. Se excluye el tiempo añadido. Por 90 = métrica / minutos × 90. No se calcula si faltan minutos.'],['Entradas e intercepciones','Entradas: duelos con tipo Tackle. Intercepciones: eventos Interception. Su volumen está condicionado por el sistema de juego y el tiempo que se pasa defendiendo.'],['Portería a cero y porcentaje de paradas','Portería a cero: el equipo no encaja y el portero juega al menos 60 minutos en portería. Porcentaje = paradas / (paradas + goles encajados), incluidos autogoles.']];
$('#terms').innerHTML=terms.map((t,i)=>'<article class="panel"><span class="badge">'+String(i+1).padStart(2,'0')+'</span><h2 class="detailtitle">'+t[0]+'</h2><p>'+t[1]+'</p></article>').join('');
$$('nav button').forEach(b=>b.onclick=()=>navigate(b.dataset.view));$$('[data-pos]').forEach(b=>b.onclick=()=>{pos=b.dataset.pos;sort=pos==='POR'?'saves':pos==='DEF'?'tackles':pos==='MED'?'assists':'goals';direction=-1;$$('[data-pos]').forEach(q=>q.classList.toggle('on',q===b));renderTable();});$$('[data-unit]').forEach(b=>b.onclick=()=>{unit=b.dataset.unit;$$('[data-unit]').forEach(q=>q.classList.toggle('on',q===b));dashboard();renderTable();renderLeaders();renderCompare();});$('#search').oninput=renderTable;$('#teamfilter').onchange=renderTable;$('#allplayers').onclick=()=>navigate('players');$('.close').onclick=()=>$('#detail').close();
$('#teamfilter').innerHTML='<option value="">Todos los equipos</option>'+[...new Set(players().map(p=>p.team))].sort().map(t=>'<option>'+esc(t)+'</option>').join('');
$('#export').onclick=()=>{const cols=columns(),metadata=data.metadata;const head=['StatsBomb Open Data',metadata.competition,metadata.season,metadata.imported_matches+'/'+metadata.available_matches+' partidos',unit==='90'?'POR 90 MIN':'TOTALES'];const csv='\uFEFF'+[head,cols.map(k=>k==='name'&&view==='teams'?'Equipo':labels[k]),...rows().map(p=>cols.map(k=>typeof p[k]==='string'?p[k]:metric(p,k)??''))].map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(';')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download='grada-statsbomb-2022-'+(view==='teams'?'equipos':'jugadores')+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
if(loaded){const m=data.metadata;$('#league').innerHTML='<option>'+esc(m.competition)+'</option>';$('#season').innerHTML='<option>'+esc(m.season)+'</option>';$('.scope').textContent=m.imported_matches+'/'+m.available_matches+' partidos · '+(m.complete?'cobertura completa':'cobertura parcial');$('.status').textContent='StatsBomb Open Data';$('#data-status').textContent=m.imported_matches+'/'+m.available_matches+' partidos importados de '+m.competition+' '+m.season+'. '+(m.complete?'':'Cobertura parcial: los rankings no representan toda la competición.');$('#database').classList.remove('hidden');$('#jsondownload').classList.remove('hidden');}else{$('#league').innerHTML='<option>Mundial masculino</option>';$('#season').innerHTML='<option>2022 · pendiente de importar</option>';$('.scope').textContent='Sin datos importados';$('.status').textContent='Pendiente de importar';$('#data-status').textContent='Aún no hay datos descargados. Ejecuta el importador de StatsBomb incluido en el proyecto o su flujo de GitHub Actions. La web no muestra cifras ficticias.';}
$('#league').disabled=true;$('#season').disabled=true;dashboard();renderLeaders();renderTable();renderCompare();
